using System.ComponentModel.DataAnnotations;
namespace RaceDay.MvC.Models;
public class LoginViewModel { [Required,EmailAddress] public string Email {get;set;}=""; [Required,DataType(DataType.Password)] public string Password {get;set;}=""; }
public class RegisterViewModel { [Required] public string FirstName {get;set;}=""; [Required] public string LastName {get;set;}=""; [Required,EmailAddress] public string Email {get;set;}=""; [Required,MinLength(8),DataType(DataType.Password)] public string Password {get;set;}=""; public string? PhoneNumber {get;set;} [Required] public string Role {get;set;}="Participant"; }
public class EventViewModel { public int EventID {get;set;} public int OrganiserID {get;set;} public int TotalEnrolments {get;set;} public bool HasBanner {get;set;} [Required] public string EventName {get;set;}=""; public string? Description {get;set;} [Required,DataType(DataType.Date)] public DateTime EventDate {get;set;}=DateTime.Today.AddDays(7); public TimeSpan? StartTime {get;set;} [Required] public string Location {get;set;}=""; [Range(0.1,1000)] public decimal Distance {get;set;}=5; [Required] public string EventType {get;set;}="Run"; public string? StartLocation {get;set;} public string? FinishLocation {get;set;} public string Status {get;set;}="Open"; public DateTime CreatedAt {get;set;} public List<EventCategoryViewModel> Categories {get;set;}=new(); }
public class EventCategoryViewModel { public int EventCategoryID {get;set;} public int EventID {get;set;} public int CategoryID {get;set;} public decimal EntryFee {get;set;} public int? MaximumParticipants {get;set;} public CategoryViewModel? Category {get;set;} }
public class CategoryViewModel { public int CategoryID {get;set;} public string CategoryName {get;set;}=""; public string CategoryType {get;set;}="Age"; public string ActivityType {get;set;}="Run"; public decimal? Distance {get;set;} public int? MinimumAge {get;set;} public int? MaximumAge {get;set;} public string? Description {get;set;} public int EventCategoryID {get;set;} public int EventID {get;set;} public decimal EntryFee {get;set;} }
public class EnrolmentViewModel { public int EnrolmentID {get;set;} public int UserID {get;set;} public int EventCategoryID {get;set;} public string? Participant {get;set;} public string? Category {get;set;} public DateTime EnrolmentDate {get;set;} public string? RaceNumber {get;set;} public string EnrolmentStatus {get;set;}="Pending"; public string? EventName {get;set;} public string? CategoryName {get;set;} }
public class ResultViewModel { public int ResultID {get;set;} public int EnrolmentID {get;set;} public TimeSpan? FinishTime {get;set;} public int? Position {get;set;} public int? CategoryPosition {get;set;} public decimal? Pace {get;set;} public string ResultStatus {get;set;}="Published"; public string? EventName {get;set;} public DateTime? EventDate {get;set;} public string? CategoryName {get;set;} public int TotalFinishers {get;set;} public string PositionDisplay => Position is null ? "—" : $"{Ordinal(Position.Value)} out of {TotalFinishers}"; private static string Ordinal(int value) => value % 100 is 11 or 12 or 13 ? $"{value}th" : $"{value}{(value % 10) switch { 1 => "st", 2 => "nd", 3 => "rd", _ => "th" }}"; }
public class ProfileViewModel { public int UserID {get;set;} public string FirstName {get;set;}=""; public string LastName {get;set;}=""; public string Email {get;set;}=""; public string? PhoneNumber {get;set;} public string Role {get;set;}="Participant"; public DateTime CreatedAt {get;set;} public bool HasProfileImage {get;set;} }